    return ' '.join(f"{k[:3]}={v if not isinstance(v,dict) else 'IDX'}" for k,v in t.items())
seen=collections.Counter()
for f in fs:
    t=json.load(open(f)); o=t['outcome']
    seen[o['case_id']]+=1
    if seen[o['case_id']]>2 and o['case_id'] not in('case:D02','case:P05'): continue
    c=t['case']; b=c['buyer']
    print(f"\n##### {o['case_id']} {o['strategy']} score={o['score']:.3f} goal={o['goal']} negotiable={c['negotiable']} opts={ {k:v for k,v in c['term_options'].items()} } cur={b.get('current_unit_price')} fb={b.get('fallback_unit_price')} alt={b.get('alternative',{}).get('kind')} deal={o.get('supplier_id')} {ts(o['terms'] or {})}")
    bo=collections.defaultdict(list)
    for x in t.get('backoffice') or []: bo[(x['supplier_id'],x['round'])].append(f"{x['from'][:6]}>{x['to'][:6]}:{x['text'][:70]}")
    for e in t['trace']:
        m=e['move']
        if e['actor']=='buyer':
            cl=[(c['type'],list(c.get('asserted',{}).values())) for c in (m.get('interpreted') or {}).get('claims',[])]
            print(f" r{e['round']} BUY->{m.get('supplier_id','')[-7:]} {m.get('type')} | "+' || '.join(ts(s['terms']) for s in m.get('term_sheets') or [])+f" claims={cl} {m.get('action') or ''}")
        else:
            print(f" r{e['round']} {e['actor'][-7:]} [{m['status']}] {ts(m['terms'])} cr={[c['result'][:4] for c in m.get('claim_results',[])]} alts={len(m.get('alternatives') or [])}")
            for r in e['reasons'][:7]: print('      ·',r[:110])
            for x in bo.get((e['actor'],e['round']),[]): 
                if 'attached' not in x: print('      BO',x)
