"""How a simulated supplier prices a term structure.

A supplier holds one number per round: V, the price it wants on its own opening structure. Any other
structure costs V times a factor - a rate per term (payment days, lead time, effective date, contract
length, index clause, quality commitment, volume) - plus the freight leg it carries. The rates are fitted
from the alternatives the arena's suppliers quote in one e-mail ("alternatively, with 14 days net: EUR ..."):
two prices at the same V.
"""

from datetime import date

from arena_kit.cost import closing_terms

# one rate per feature; a feature is the distance of a structure from the supplier's opening structure
FEATURES = ("pay", "lead", "eff", "con", "idx", "deadband", "ppm", "chargeback", "vol")


def _months(later: str | None, earlier: str | None) -> float:
    try:
        return (date.fromisoformat(later) - date.fromisoformat(earlier)).days / 30.4
    except (TypeError, ValueError):
        return 0.0


def features(case: dict, terms: dict, ref: dict) -> dict[str, float]:
    """The structure `terms` against the supplier's opening structure `ref` (both closed with its standard terms)."""
    t = closing_terms(case, terms, ref)

    def num(src, field):
        return float(src.get(field) or 0)

    clause, ref_clause = t.get("index_clause") or None, ref.get("index_clause") or None
    return {
        "pay": (num(t, "payment_days") - num(ref, "payment_days")) / 360,
        "lead": (num(ref, "lead_time_days") - num(t, "lead_time_days")) / 30,  # faster than its opening
        "eff": _months(t.get("effective_date"), ref.get("effective_date")),
        "con": (num(t, "contract_months") - num(ref, "contract_months")) / 12,
        "idx": float(bool(clause)) - float(bool(ref_clause)),
        "deadband": ((clause or {}).get("deadband_pct") or 0) / 100 - ((ref_clause or {}).get("deadband_pct") or 0) / 100,
        "ppm": (num(ref, "ppm_commitment") - num(t, "ppm_commitment")) / 1000,  # tighter than its opening
        "chargeback": (num(t, "chargeback_eur_per_complaint") - num(ref, "chargeback_eur_per_complaint")) / 1000,
        "vol": (num(t, "volume_per_year") / num(ref, "volume_per_year") - 1) if num(ref, "volume_per_year") else 0.0,
    }


def factor(rates: dict[str, float], x: dict[str, float]) -> float:
    return max(0.2, 1 + sum(rates.get(f, 0.0) * x[f] for f in FEATURES))


def freight_leg(case: dict, terms: dict, ref: dict) -> float:
    """EUR per unit the supplier carries more than on its opening Incoterm."""
    freight = case["buyer"]["freight_eur_per_unit"]
    t = closing_terms(case, terms, ref)
    return freight.get(ref.get("incoterm"), 0.0) - freight.get(t.get("incoterm"), 0.0)


def price_for(case: dict, rates: dict, ref: dict, value: float, terms: dict) -> float:
    """The unit price that is worth `value` (on the opening structure) on the structure `terms`."""
    return value * factor(rates, features(case, terms, ref)) + freight_leg(case, terms, ref)


def value_of(case: dict, rates: dict, ref: dict, terms: dict) -> float:
    """The opening-structure price a term sheet is worth to the supplier."""
    return (terms["unit_price"] - freight_leg(case, terms, ref)) / factor(rates, features(case, terms, ref))


def solve(a: list[list[float]], b: list[float]) -> list[float]:
    """Gaussian elimination with partial pivoting, for the small ridge systems of the fit."""
    n = len(b)
    m = [row[:] + [b[i]] for i, row in enumerate(a)]
    for col in range(n):
        pivot = max(range(col, n), key=lambda r: abs(m[r][col]))
        m[col], m[pivot] = m[pivot], m[col]
        if abs(m[col][col]) < 1e-12:
            continue
        for r in range(n):
            if r != col:
                k = m[r][col] / m[col][col]
                m[r] = [v - k * w for v, w in zip(m[r], m[col], strict=True)]
    return [m[i][n] / m[i][i] if abs(m[i][i]) > 1e-12 else 0.0 for i in range(n)]


def fit_rates(pairs: list[tuple[dict, float, dict, float]], prior: dict[str, float], ridge: float) -> dict[str, float]:
    """Rates from pairs (x1, P1, x2, P2) of two prices at one V, freight removed: P1 (1 + r.x2) = P2 (1 + r.x1).
    Ridge towards `prior`, so a supplier with one alternative keeps the pooled rates for the other terms."""
    n = len(FEATURES)
    a = [[ridge if i == j else 0.0 for j in range(n)] for i in range(n)]
    b = [ridge * prior.get(f, 0.0) for f in FEATURES]
    for x1, p1, x2, p2 in pairs:
        scale = (p1 + p2) / 2
        row = [(p1 * x2[f] - p2 * x1[f]) / scale for f in FEATURES]
        target = (p2 - p1) / scale
        for i in range(n):
            b[i] += row[i] * target
            for j in range(n):
                a[i][j] += row[i] * row[j]
    return {f: round(v, 5) for f, v in zip(FEATURES, solve(a, b), strict=True)}

"""The simulated supplier: one value V per round, moved by what the buyer just did.

Nothing here is a rule of the arena - the arena does not hand out its suppliers. It is the smallest model that
reproduces what the recorded sessions show:

  - the supplier answers on the buyer's sheet it likes best, at its own price for that structure;
  - it concedes a share of the gap between its price and its floor, and how large a share depends on what
    the buyer did: moved, stood still, brought a rival quote or another argument that convinced it;
  - a big step comes in two halves ("we need to clarify this internally"), the second on the next e-mail;
  - after a few rounds it calls its offer final and mostly stays there;
  - it agrees as soon as a sheet the buyer sent is worth its new price.

Step shares and the round of the final offer are not parameters but resampled from the recorded moves of that
supplier (pooled over all suppliers where it has too few), so the simulator is as noisy as the bots are.
"""

import random
from dataclasses import dataclass, field

from negotiator.sim.pricing import price_for, value_of

KINDS = ("rival", "claim", "moved", "still", "pending", "final")
MIN_OWN = 2  # recorded moves of a kind a supplier needs before its own are used instead of the pool
POOL_WEIGHT = 1.0  # pseudo-observations of the pooled final-offer rate
WALK_PUSHES, WALK_P = 3, 0.5  # NOT calibrated: no recorded supplier walked away. Pushes past a final offer.
EPS = 1e-9


@dataclass
class Profile:
    """What the calibration knows about one supplier in one case."""

    supplier_id: str
    opening: dict  # its opening term sheet
    ref: dict  # the opening closed with its standard and the case's fixed terms
    standard: dict  # the standard terms of its quote PDF
    rates: dict  # pricing.FEATURES -> rate
    floor: float  # the lowest V it accepts
    quantum: float = 0.01  # its price steps
    min_lead: int | None = None  # the fastest delivery it quoted
    steps: dict = field(default_factory=dict)  # kind[/first] -> [[share of the gap, clarify?], ...]
    finals: dict = field(default_factory=dict)  # reply number -> [final offers, replies seen]
    convinced: dict = field(default_factory=dict)  # claim type -> [took into account, checked]
    full_cost: float | None = None  # for the relationship term of C, where a recorded deal showed it
    floor_source: str = ""

    @property
    def opening_value(self) -> float:
        return self.opening["unit_price"]


@dataclass
class Thread:
    """The supplier's side of one thread."""

    profile: Profile
    pool: Profile  # the same tables over every supplier
    rng: random.Random
    value: float = 0.0
    replies: int = 0
    status: str = "open"
    stills: int = 0
    pushes: int = 0
    pending: float = 0.0  # the half of a step it still owes
    best_buyer: tuple[float, dict] | None = None  # the best sheet the buyer ever sent, in V
    terms: dict = field(default_factory=dict)

    def __post_init__(self):
        self.value = self.profile.opening_value
        self.terms = dict(self.profile.opening)

    # -- tables ------------------------------------------------------------------------------------
    def _step(self, kind: str) -> tuple[float, bool]:
        first = "/first" if self.replies == 0 else ""
        for table, key, need in (
            (self.profile.steps, kind + first, MIN_OWN),
            (self.profile.steps, kind, MIN_OWN),
            (self.pool.steps, kind + first, 1),
            (self.pool.steps, kind, 1),
        ):
            if len(table.get(key, [])) >= need:
                share, clarify = self.rng.choice(table[key])
                return share, bool(clarify)
        return 0.0, False

    def _final_rate(self, kind: str) -> float:
        key = f"{min(self.replies + 1, 9)}/{'still' if kind == 'still' else 'move'}"
        k, n = self.profile.finals.get(key, (0, 0))
        pk, pn = self.pool.finals.get(key, (0, 0))
        prior = pk / pn if pn else 0.0
        return (k + POOL_WEIGHT * prior) / (n + POOL_WEIGHT)

    def convincing(self, claim_type: str) -> bool:
        k, n = self.profile.convinced.get(claim_type, (0, 0))
        pk, pn = self.pool.convinced.get(claim_type, (0, 0))
        prior = pk / pn if pn else 0.5
        return self.rng.random() < (k + prior) / (n + 1)

    # -- one reply ---------------------------------------------------------------------------------
    def reply(self, case: dict, sheets: list[dict], claims: list[str]) -> dict:
        """The answer to one buyer e-mail. `claims`: the types of the arguments that checked out, new this
        round. Returns the status, the standing terms and the reasons in words."""
        p, reasons = self.profile, []
        values = [(value_of(case, p.rates, p.ref, self._feasible(case, s)), s) for s in sheets]
        top = max(values, key=lambda vs: vs[0]) if values else None
        moved = bool(top) and (self.best_buyer is None or top[0] > self.best_buyer[0] + EPS)
        if top and (self.best_buyer is None or top[0] >= self.best_buyer[0]):
            self.best_buyer = top
        won = [c for c in claims if self.convincing(c)]
        if self.status == "final_offer":
            kind = "final"
        elif self.pending:
            kind = "pending"
        elif "rival_quote" in won:
            kind = "rival"
        elif won:
            kind = "claim"
        else:
            kind = "moved" if moved else "still"
        for c in claims:
            reasons.append(
                f"We checked the {c.replace('_', ' ')} data you cited; it holds"
                + (" and we took it into account." if c in won else ", but it does not change our calculation.")
            )

        gap = max(0.0, self.value - p.floor)
        if kind == "pending":
            step, self.pending = self.pending, 0.0
            reasons.append("We have clarified this internally and can move further on the price.")
        else:
            share, clarify = self._step(kind)
            step = share * gap
            if clarify and step > 0:  # half now, the rest after the boss has checked
                self.pending = step / 2
                step /= 2
                reasons.append("We need to clarify this internally - we will come back to you on price.")
        if kind == "still" and step == 0:
            self.stills += 1
            reasons.append("Without movement from your side we cannot move either.")
        self.value = max(p.floor, self.value - min(step, gap))

        if kind == "final":
            self.pushes += not moved
            if self.pushes >= WALK_PUSHES and self.rng.random() < WALK_P:
                self.status = "walked_away"
                return self._out(case, ["We end the talks here."])
        structure = self._feasible(case, top[1]) if top else self.terms
        if self.best_buyer and self.best_buyer[0] >= self.value - EPS:
            self.status, self.value = "agreed", self.best_buyer[0]
            self.terms = dict(self._feasible(case, self.best_buyer[1]))
            self.replies += 1
            return self._out(case, [*reasons, "We can agree to your terms."])
        final = self.status == "final_offer" or self.rng.random() < self._final_rate(kind) or gap <= p.quantum
        self.status = "final_offer" if final else "open"
        price = price_for(case, p.rates, p.ref, self.value, structure)
        self.terms = {**structure, "unit_price": max(p.quantum, round(round(price / p.quantum) * p.quantum, 2))}
        self.value = value_of(case, p.rates, p.ref, self.terms)  # what it wrote, after rounding
        self.replies += 1
        if final:
            reasons.append("This is our final offer.")
        return self._out(case, reasons)

    def _feasible(self, case: dict, sheet: dict) -> dict:
        """The buyer's structure, with a delivery it cannot make replaced by its earliest."""
        lead = sheet.get("lead_time_days")
        if lead is not None and self.profile.min_lead is not None and lead < self.profile.min_lead:
            return {**sheet, "lead_time_days": self.profile.min_lead}
        return sheet

    def _out(self, case: dict, reasons: list[str]) -> dict:
        return {"status": self.status, "terms": dict(self.terms), "reasons": reasons}

"""Fit the simulated suppliers from our recorded arena sessions (`runs/*/sessions/*.json`).

Per supplier and case: its opening and standard terms (as quoted), its pricing rates (from the alternatives
it quoted in one e-mail), its floor (the price at which the best package it could still accept costs exactly
the `c_best` the arena published for the case), and tables of what it did after each kind of buyer move.
The result is a JSON file under `agent/data/` (git-ignored): values from replays never enter the code.
"""

import itertools
import json
import statistics
from collections import defaultdict
from dataclasses import asdict
from pathlib import Path

from arena_kit.cost import closing_terms, must_haves_ok, relationship_cost, total_cost
from arena_kit.docs import quote_terms

from negotiator.sim.pricing import FEATURES, features, fit_rates, freight_leg, price_for, value_of
from negotiator.sim.supplier import Profile

POOL_RIDGE, OWN_RIDGE = 1e-4, 2e-4
CLARIFY = "clarify this internally"
TOOK = "took into account"
FLOOR_MARGIN = 0.25  # an unidentified floor sits this share of the observed give below the lowest offer seen


def load_sessions(runs_dir: Path) -> list[dict]:
    """Every recorded arena session with a result (simulator runs are kept elsewhere)."""
    out = []
    for path in sorted(runs_dir.glob("*/sessions/*.json")):
        t = json.loads(path.read_text(encoding="utf-8"))
        if t.get("trace") and (t.get("outcome") or {}).get("c_best") is not None:
            t["_id"] = f"{path.parent.parent.name}/{path.stem}"
            out.append(t)
    return out


def opening_of(t: dict, sup: str) -> tuple[dict, dict, dict]:
    """A supplier's opening sheet, its standard terms and its opening structure in full."""
    case, first = t["case"], t["threads"][sup]["messages"][0]
    text = next((a.get("text") for a in first.get("attachments") or [] if a.get("text")), "") or ""
    standard = quote_terms(text).get("standard", {})
    opening = first["term_sheets"][0]["terms"]
    return opening, standard, closing_terms(case, opening, {**standard, **case.get("fixed_terms", {})})


def _moves(t: dict, sup: str):
    """The thread as (buyer move or None, supplier move, reasons), the opening first."""
    buyer = None
    for e in t["trace"]:
        m = e["move"]
        if e["actor"] == "buyer":
            if m.get("supplier_id") == sup and m.get("type") in ("message", "timeout"):
                buyer = m
        elif e["actor"] == sup:
            yield buyer, m, e.get("reasons") or []
            buyer = None


def _rates(sessions: list[dict]) -> tuple[dict, dict]:
    pairs = defaultdict(list)
    for t in sessions:
        case = t["case"]
        for sup in t["threads"]:
            ref = opening_of(t, sup)[2]
            for _, m, _ in _moves(t, sup):
                for alt in m.get("alternatives") or []:
                    a = alt.get("terms", alt)
                    if a.get("unit_price") is None or m["terms"].get("unit_price") is None:
                        continue
                    pairs[(case["case_id"], sup)].append(
                        (
                            features(case, m["terms"], ref),
                            m["terms"]["unit_price"] - freight_leg(case, m["terms"], ref),
                            features(case, a, ref),
                            a["unit_price"] - freight_leg(case, a, ref),
                        )
                    )
    pool = fit_rates([p for v in pairs.values() for p in v], {}, POOL_RIDGE)
    return pool, {k: fit_rates(v, pool, OWN_RIDGE) for k, v in pairs.items()}


def combos(case: dict, min_lead: int | None = None):
    """Every structure the case allows (without a price) that keeps the must-haves."""
    fields = [f for f in case["negotiable"] if f != "unit_price"]
    options = [case["term_options"].get(f) or [None] for f in fields]
    for values in itertools.product(*options):
        terms = dict(zip(fields, values, strict=True))
        if min_lead is not None and (terms.get("lead_time_days") or min_lead) < min_lead:
            continue
        yield terms


def best_cost(case: dict, p: Profile, value: float | None = None) -> float:
    """C of the best package the supplier accepts at `value` (default: its floor), every lever applied."""
    value, best = p.floor if value is None else value, float("inf")
    for terms in combos(case, p.min_lead):
        sheet = {**terms, "unit_price": round(price_for(case, p.rates, p.ref, value, terms), 2)}
        if must_haves_ok(case, sheet, p.ref):
            best = min(best, total_cost(case, sheet, p.ref))
    return best


def _floor_for(case: dict, p: Profile, c_best: float) -> float:
    """The value at which the supplier's best package costs exactly c_best (bisection: C rises with the value)."""
    lo, hi = p.opening_value * 0.3, p.opening_value * 1.2
    for _ in range(50):
        mid = (lo + hi) / 2
        lo, hi = (mid, hi) if best_cost(case, p, mid) < c_best else (lo, mid)
    return hi


def _kind(case, p: Profile, buyer, reasons, prev_status, prev_reasons, best_buyer) -> tuple[str, float | None]:
    """What the buyer did before a recorded supplier move, in the words of `supplier.KINDS`."""
    sheets = [s["terms"] for s in (buyer or {}).get("term_sheets") or [] if s["terms"].get("unit_price")]
    top = max((value_of(case, p.rates, p.ref, s) for s in sheets), default=None)
    moved = top is not None and (best_buyer is None or top > best_buyer + 1e-9)
    text = " ".join(reasons)
    if prev_status == "final_offer":
        return "final", top
    if any(CLARIFY in r for r in prev_reasons):
        return "pending", top
    if "rival quote" in text and TOOK in text and "rival quote data you cited; it holds and" in text:
        return "rival", top
    if TOOK in text:
        return "claim", top
    return ("moved" if moved else "still"), top


def calibrate(sessions: list[dict]) -> dict:
    """The model: one profile per (case, supplier), the pool over all of them, and the cases themselves."""
    pool_rates, own_rates = _rates(sessions)
    profiles: dict[str, Profile] = {}
    cases, results, seen = {}, {}, defaultdict(list)
    for t in sessions:
        case, o = t["case"], t["outcome"]
        cases[case["case_id"]] = case
        results[case["case_id"]] = {"c_open": o["c_open"], "c_best": o["c_best"], "c_alt": o.get("c_alt")}
        for sup in t["threads"]:
            key = f"{case['case_id']}|{sup}"
            if key not in profiles:
                opening, standard, ref = opening_of(t, sup)
                rates = own_rates.get((case["case_id"], sup), pool_rates)
                profiles[key] = Profile(sup, opening, ref, standard, rates, floor=0.0)
            seen[key].append(t)

    # what each supplier showed: its lowest value, its price steps, the fastest delivery it refused to beat
    lowest = {}
    for key, p in profiles.items():
        case = cases[key.split("|")[0]]
        prices, refused = [], []
        for t in seen[key]:
            for buyer, m, _ in _moves(t, p.supplier_id):
                if m["terms"].get("unit_price") is None:
                    continue
                prices.append(m["terms"]["unit_price"])
                asked = [s["terms"].get("lead_time_days") for s in (buyer or {}).get("term_sheets") or []]
                got = m["terms"].get("lead_time_days")
                if got is not None and asked and all(a is not None and a < got for a in asked):
                    refused.append(got)
        p.min_lead = min(refused) if refused else None
        p.quantum = 0.1 if all(abs(x * 10 - round(x * 10)) < 1e-6 for x in prices) else 0.01
        lowest[key] = min(
            value_of(case, p.rates, p.ref, m["terms"])
            for t in seen[key]
            for _, m, _ in _moves(t, p.supplier_id)
            if m["terms"].get("unit_price") is not None
        )

    # floors: per case the supplier whose floor explains c_best, the others below what they showed
    for case_id, case in cases.items():
        keys = [k for k in profiles if k.startswith(case_id + "|")]
        r = results[case_id]
        by_alt = r["c_alt"] is not None and abs(r["c_alt"] - r["c_best"]) < 0.02
        fits = {} if by_alt else {k: _floor_for(case, profiles[k], r["c_best"]) for k in keys}
        able = {k: f for k, f in fits.items() if f < lowest[k]}
        maker = min(able, key=lambda k: best_cost(case, profiles[k], lowest[k])) if able else None
        for k in keys:
            p = profiles[k]
            if k == maker:
                p.floor, p.floor_source = fits[k], "c_best"
            else:
                guess = lowest[k] - FLOOR_MARGIN * (p.opening_value - lowest[k])
                p.floor, p.floor_source = max(guess, fits.get(k, 0.0)), "below the lowest offer seen"
            p.floor = round(min(p.floor, lowest[k]), 4)

    # the tables: steps per kind, final offers per reply number, arguments that convinced
    for key, p in profiles.items():
        case = cases[key.split("|")[0]]
        steps, finals, convinced = defaultdict(list), defaultdict(lambda: [0, 0]), defaultdict(lambda: [0, 0])
        costs = []
        for t in seen[key]:
            value, status, prev_reasons, best_buyer, n = p.opening_value, "open", [], None, 0
            for buyer, m, reasons in _moves(t, p.supplier_id):
                if buyer is None or m["terms"].get("unit_price") is None:
                    prev_reasons = reasons
                    continue
                kind, top = _kind(case, p, buyer, reasons, status, prev_reasons, best_buyer)
                best_buyer = max(x for x in (best_buyer, top) if x is not None) if top is not None else best_buyer
                new = value_of(case, p.rates, p.ref, m["terms"])
                gap = value - p.floor
                if m["status"] != "agreed" and gap > p.quantum / 2:
                    share = min(1.0, max(0.0, (value - new) / gap))
                    clarify = any(CLARIFY in r for r in reasons)
                    steps[kind].append([round(share, 4), clarify])
                    if n == 0:
                        steps[kind + "/first"].append([round(share, 4), clarify])
                if status != "final_offer" and m["status"] != "agreed":
                    slot = finals[f"{min(n + 1, 9)}/{'still' if kind == 'still' else 'move'}"]
                    slot[0] += m["status"] == "final_offer"
                    slot[1] += 1
                for c in (buyer.get("interpreted") or {}).get("claims") or []:
                    label = c["type"].replace("_", " ")
                    checked = [r for r in reasons if f"the {label} data you cited" in r]
                    if checked:
                        convinced[c["type"]][0] += any(TOOK in r for r in checked)
                        convinced[c["type"]][1] += 1
                value, status, prev_reasons, n = new, m["status"], reasons, n + 1
            charge = (t["outcome"].get("cost_breakdown") or {}).get("relationship") or 0
            if charge > 0 and t["outcome"].get("supplier_id") == p.supplier_id:
                costs.append(_full_cost(case, p, t["outcome"]["terms"], charge))
        p.steps, p.finals, p.convinced = dict(steps), dict(finals), dict(convinced)
        p.full_cost = round(statistics.median(costs), 4) if costs else None

    pool = Profile("pool", {"unit_price": 1.0}, {}, {}, pool_rates, floor=0.0)
    for table in ("steps", "finals", "convinced"):
        merged: dict = {}
        for p in profiles.values():
            for k, v in getattr(p, table).items():
                merged[k] = merged.get(k, []) + v if table == "steps" else [a + b for a, b in zip(merged.get(k, [0, 0]), v)]
        setattr(pool, table, merged)
    return {
        "cases": cases,
        "results": results,
        "profiles": {k: asdict(p) for k, p in profiles.items()},
        "pool": asdict(pool),
        "sessions": len(sessions),
        "features": list(FEATURES),
    }


def _full_cost(case: dict, p: Profile, terms: dict, charge: float) -> float:
    """The supplier's full cost per unit that makes the kit's relationship term equal the recorded charge."""
    lo, hi = 0.0, terms["unit_price"] * 1.5
    for _ in range(50):
        mid = (lo + hi) / 2
        got = relationship_cost(case, terms, supplier=estimate(p, mid))
        lo, hi = (mid, hi) if got < charge else (lo, mid)
    return hi


def estimate(p: Profile, full_cost: float | None = None) -> dict | None:
    """The kit's `supplier` argument for the relationship term of C, where the full cost is known."""
    cost = p.full_cost if full_cost is None else full_cost
    if cost is None:
        return None
    return {"standard": p.ref, "interest_rate": max(0.0, p.rates.get("pay", 0.08)), "full_cost": cost}


def load_model(path: Path) -> dict:
    model = json.loads(path.read_text(encoding="utf-8"))
    model["profiles"] = {k: Profile(**v) for k, v in model["profiles"].items()}
    model["pool"] = Profile(**model["pool"])
    return model


def as_objects(model: dict) -> dict:
    """A freshly calibrated model in the shape `load_model` returns."""
    return load_model_from(json.loads(json.dumps(model)))


def load_model_from(raw: dict) -> dict:
    raw["profiles"] = {k: Profile(**v) for k, v in raw["profiles"].items()}
    raw["pool"] = Profile(**raw["pool"])
    return raw

